def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Extract sequences
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = me.count('D')

    # Immediate strong signals
    if opp_d == 0:
        # Opponent never defected. On final round, exploit.
        if n >= 99:
            return 'D'
        # Otherwise stay cooperative, but consider a late probe.
        return 'C'
    if opp_c == 0:
        return 'D'

    # Recent window stats
    window = 12
    recent = history[-window:] if n >= window else history
    rlen = len(recent)
    ropp_c = sum(1 for a, b in recent if b == 'C')
    ropp_d = rlen - ropp_c
    rmy_d = sum(1 for a, b in recent if a == 'D')

    my_last, opp_last = history[-1]

    # Strong recent mutual cooperation: stay cooperative, but exploit near end.
    if ropp_d == 0:
        if n >= 98:
            return 'D'
        # Very reliable cooperator; occasionally probe late.
        if n >= 30 and opp_d <= 1 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Strong recent defection: punish.
    if ropp_c == 0:
        return 'D'

    # Detect defender type: does opponent defect more after our C than after our D?
    after_C_n = 0
    after_C_D = 0
    after_D_n = 0
    after_D_D = 0
    limit = min(n - 1, 40)
    for i in range(n - 1 - limit, n - 1):
        if me[i] == 'C':
            after_C_n += 1
            if opp[i + 1] == 'D':
                after_C_D += 1
        else:
            after_D_n += 1
            if opp[i + 1] == 'D':
                after_D_D += 1

    p_d_after_c = after_C_D / after_C_n if after_C_n > 0 else 0.0
    p_d_after_d = after_D_D / after_D_n if after_D_n > 0 else 0.0

    # Exploit-tolerant opponent: defecting hurts less than cooperating.
    if n >= 15 and after_D_n >= 3 and after_C_n >= 3:
        if p_d_after_c > p_d_after_d + 0.25:
            # They punish our cooperation more than our defection -> defect.
            return 'D'
        if p_d_after_d > p_d_after_c + 0.35:
            # They punish defection strongly -> cooperate.
            return 'C'

    # Near endgame: if opponent has been mostly cooperative, exploit.
    remaining = 100 - n
    if remaining <= 3:
        if opp_c >= opp_d + 3 and ropp_c >= ropp_d:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Tit-for-tat with controlled forgiveness, biased toward cooperation.
    if opp_last == 'C':
        # If we've been defecting a lot and opponent still cooperates, keep cooperating.
        if rmy_d >= 4 and ropp_d <= 1:
            return 'C'
        # Rare late probe against very cooperative opponent.
        if n >= 50 and opp_d <= 2 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Opponent defected last round.
    # Count current defect streak.
    streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            streak += 1
        else:
            break

    # Long streak: punish.
    if streak >= 3:
        return 'D'

    # If opponent's overall defection rate is very low, forgive occasionally.
    opp_rate = opp_d / n
    if opp_rate <= 0.12:
        # Forgive most of the time, but retaliate on 2nd consecutive.
        if streak >= 2:
            return 'D'
        return 'C'

    if opp_rate <= 0.3:
        # Moderate: retaliate once, then forgive if they return to C.
        if streak >= 2:
            return 'D'
        # Single defection: retaliate, but occasionally forgive.
        return 'D' if rng.random() < 0.7 else 'C'

    if opp_rate <= 0.55:
        return 'D'

    # Very defective: exploit-punish, occasionally probe.
    return 'D' if rng.random() < 0.9 else 'C'
